// Two modes. MOCK (default): uses src/mock/demo.json generated by scripts/export_demo_json.py.
// LIVE: set VITE_API_URL (local: `python scripts/dev_server.py`, then VITE_API_URL=http://localhost:8787).
import demo from './mock/demo.json'

const BASE = import.meta.env.VITE_API_URL || ''
export const MODE = BASE ? 'LIVE' : 'MOCK'

async function call(method, path, body) {
  const r = await fetch(BASE + path, { method, headers: { 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined })
  if (!r.ok) throw new Error(`${method} ${path} failed: ${r.status}`)
  return r.json()
}

export async function createProject() {
  if (MODE === 'MOCK') return { id: 'mock', result: demo.day0, drafts: demo.day0.drafts }
  return call('POST', '/projects')
}
export async function advance(project, days) {
  if (MODE === 'MOCK') {
    // Only two frames are bundled (day 0 and day 50), so the mock clock stops at day 50.
    const day = Math.min(project.result.today_day + days, 50)
    const result = { ...(day >= 40 ? demo.day50 : demo.day0), today_day: day }
    return { ...project, result, drafts: result.drafts }
  }
  return call('POST', `/projects/${project.id}/advance`, { days })
}
export async function sendDiscomReply(project, text) {
  if (MODE === 'MOCK') return { ...project, result: demo.day50_reply, drafts: demo.day50_reply.drafts }
  return call('POST', `/projects/${project.id}/discom-reply`, { text })
}
export async function approveDraft(project, draftId) {
  if (MODE === 'MOCK') {
    const drafts = project.drafts.map(d => (d.id === draftId ? { ...d, status: 'APPROVED' } : d))
    return { ...project, drafts, result: { ...project.result, drafts } }
  }
  return call('POST', `/projects/${project.id}/drafts/${draftId}/approve`)
}
export const DISCOM_REPLY_EXAMPLE = demo.day0.society ? 'Subject: Feasibility query. The sanctioned load for the common meter is insufficient for this capacity. Maximum permissible solar is 25 kW. Please revise.' : ''
